import {shows} from './tv-data.js';
import {createYouTubePlayer,watchURL} from './youtube-player.js';
import {safe,fold,keyword} from './experience.js';
export {shows};
// Only manually verified embeds may expose a player; unknown entries default to external playback.
const canEmbed=s=>s?.playback?.status==='verified';
const clock=s=>`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;
const url=s=>'#tv/'+s.id;
const sourceLink=(s,i)=>`<a class="tv-citation" href="${safe(s.sources[i].url)}" target="_blank" rel="noopener noreferrer" aria-label="Fonte: ${safe(s.sources[i].label)}">[${i+1}]</a>`;
const saved=()=>{try{const v=JSON.parse(localStorage.getItem('meeting.points.watchlist')||'[]');return Array.isArray(v)?v.filter(id=>shows.some(s=>s.id===id)):[];}catch{return [];}};
const saveButton=s=>`<button class="tv-save" data-save-show="${s.id}" aria-pressed="${saved().includes(s.id)}">${saved().includes(s.id)?'✓ Na sua lista':'+ Ver depois'}</button>`;
const poster=s=>`<img src="${s.poster}" width="${s.posterWidth}" height="${s.posterHeight}" alt="${safe(s.artist+' — '+s.title)}" decoding="async">`;
const card=s=>`<article class="tv-program-card" data-kind="${safe(s.kind)}" data-program="${s.id}" style="--program-color:${s.color}"><a class="tv-card-art" href="${url(s)}">${poster(s)}<span class="tv-runtime">${clock(s.length)}</span><span class="tv-card-open" aria-hidden="true">Explorar ↗</span></a><div class="tv-card-meta"><div><p class="eyebrow">${s.year} · ${s.fan?'Edição de fã':s.kind}</p><h2><a href="${url(s)}">${safe(s.artist)}</a></h2><p>${safe(s.title)}</p></div>${saveButton(s)}</div></article>`;
export function tvPage(){const s=shows[1];return `<section class="tv-heading"><div><span class="eyebrow">MEETING.POINTS / TV</span><h1>Você tinha que estar lá.</h1></div><p>Palco, imagem e tudo<br>o que acontece entre os dois.</p></section><section class="tv-hero" style="--program-color:${s.color}">${poster(s)}<div class="tv-hero-copy"><span class="eyebrow">EM CARTAZ · ${s.year} · ${clock(s.length)}</span><h2>${safe(s.artist)}<br><span>${safe(s.title)}</span></h2><p>${safe(s.tagline)}</p><a class="solid" href="${url(s)}">Entrar na sessão ↗</a></div><span class="tv-orbit" aria-hidden="true">●</span></section><section class="tv-programming"><div class="section-head"><h2>Escolha sua sessão</h2><span class="small">Curadoria de Lucas</span></div><div class="tv-library-filters" role="group" aria-label="Filtrar programas">${[['all','Todos'],['DJ set','DJ sets'],['Filme-concerto','Filmes'],['Live','Live'],['saved','Minha lista']].map(([v,label])=>`<button data-program-filter="${v}" aria-pressed="${v==='all'}">${label}</button>`).join('')}</div><label class="tv-search-label">Buscar na TV<input type="search" data-tv-search placeholder="Artista, show, música ou crédito…"></label><div class="tv-program-grid">${shows.map(card).join('')}</div><p class="tv-empty" hidden>Sua próxima sessão ainda está por aqui. Salve um programa em “Ver depois”.</p></section>`;}
export function tvDetail(id){const s=shows.find(s=>s.id===id);if(!s)return '<p class="empty">Programa não encontrado. <a href="#tv">Voltar à TV</a></p>';const next=shows[(shows.indexOf(s)+1)%shows.length];return `<article class="tv-detail" data-show-id="${s.id}" style="--program-color:${s.color}"><a class="detail-back" href="#tv">← Todas as sessões</a><section class="tv-detail-hero">${poster(s)}<div class="tv-detail-title"><p class="eyebrow">${s.year} · ${s.kind} · ${clock(s.length)}</p><h1>${safe(s.artist)}<span>${safe(s.title)}</span></h1><p>${safe(s.place)}</p><div class="tv-actions">${canEmbed(s)?'<button class="solid" data-play-program>▶ Assistir</button>':`<a class="solid" href="${watchURL(s.video)}" target="_blank" rel="noopener noreferrer">Assistir no YouTube ↗</a>`}${saveButton(s)}</div></div></section><section class="tv-intro"><p>${safe(s.intro)}</p><div><span>${s.fan?'EDIÇÃO DE FÃ':'PUBLICAÇÃO DO ARTISTA'}</span><p>${safe(s.channel)}</p><small>Upload: ${new Date(s.published).toLocaleDateString('pt-BR',{timeZone:'UTC'})}<br>Duração desta publicação: ${clock(s.length)}</small></div></section>${canEmbed(s)?`<section class="tv-theater" aria-label="Player de ${safe(s.title)}"><div class="tv-theater-toolbar"><span class="eyebrow">AGORA, SÓ O SHOW.</span><button data-cinema aria-pressed="false">Apagar as luzes ◐</button></div>${s.warning?`<p class="tv-warning">${safe(s.warning)}</p>`:''}<div class="tv-player"><button data-play-program aria-label="Reproduzir ${safe(s.title)}">${poster(s)}<span>▶</span></button></div><div class="tv-player-feedback"><p class="tv-player-status" role="status" aria-live="polite"></p><a class="text-link tv-external" href="${watchURL(s.video)}" target="_blank" rel="noopener">Assistir no YouTube ↗</a></div></section>`:`<aside class="tv-external-note"><span class="eyebrow">SESSÃO NO YOUTUBE</span><p>Este programa está disponível no YouTube. O arquivo, os créditos e as faixas continuam aqui para acompanhar a sessão.</p><a href="${watchURL(s.video)}" target="_blank" rel="noopener noreferrer">Abrir o show em outra aba ↗</a></aside>`}${s.chapters.length?`<section class="tv-chapters"><div class="section-head"><h2>Entre por qualquer parte</h2><span class="small">Tempos da publicação ${sourceLink(s,0)}</span></div><div class="tv-chapter-list">${s.chapters.map(c=>`<a data-chapter="${c.time}" href="${watchURL(s.video,c.time)}" target="_blank" rel="noopener"><time>${clock(c.time)}</time><span>${safe(c.title)}</span><span aria-hidden="true">↗</span></a>`).join('')}</div></section>`:''}<div class="tv-dossier"><div><span class="eyebrow">PARA IR ALÉM DO PLAY</span>${s.sections.map(p=>`<section><h2>${safe(p.heading)}</h2><p>${safe(p.text)} ${p.refs.map(i=>sourceLink(s,i)).join(' ')}</p></section>`).join('')}<aside class="tv-listening-note"><span class="eyebrow">UM JEITO DE ESCUTAR · LEITURA EDITORIAL</span><p>${safe(s.listen)}</p></aside></div><aside class="tv-credits"><h2>Ficha técnica</h2><dl>${s.credits.map(([role,name])=>`<div><dt>${safe(role)}</dt><dd>${safe(name)}</dd></div>`).join('')}</dl><p class="small">Créditos e limites de identificação detalhados nas fontes abaixo.</p></aside></div>${s.repertoire?`<details class="tv-repertoire"><summary>Repertório desta publicação</summary><p class="small">Ordem fornecida pelo canal, sem tempos confirmados. ${sourceLink(s,0)}</p><ol>${s.repertoire.map(t=>`<li>${safe(t)}</li>`).join('')}</ol></details>`:''}<section class="tv-sources"><h2>Fontes & arquivo</h2><ol>${s.sources.map(f=>`<li><a href="${safe(f.url)}" target="_blank" rel="noopener noreferrer">${safe(f.label)} ↗</a></li>`).join('')}</ol><p class="small">Consultado em 9 de setembro de 2026. Contexto e créditos documentados; sugestões de escuta são editoriais. Campos não confirmados não foram preenchidos por suposição.</p></section><a class="tv-next" href="${url(next)}"><span class="eyebrow">SUA PRÓXIMA SESSÃO</span><strong>${safe(next.artist)} <span>— ${safe(next.title)}</span></strong><span aria-hidden="true">↗</span></a></article>`;}
let dispose=()=>{};
export function bindTV(root){dispose();document.body.classList.remove('tv-cinema');const events=new AbortController(),opt={signal:events.signal};let currentFilter='all',searchQuery='';
 root.querySelector('[data-tv-search]')?.addEventListener('input',e=>{searchQuery=e.target.value;filter();},opt);
 const filter=()=>{let count=0;root.querySelectorAll('[data-program]').forEach(c=>{const visible=(currentFilter==='all'||currentFilter==='saved'&&saved().includes(c.dataset.program)||currentFilter===c.dataset.kind)&&searchShows(searchQuery).some(s=>s.id===c.dataset.program);c.hidden=!visible;if(visible)count++;});const empty=root.querySelector('.tv-empty');if(empty){empty.hidden=count!==0;empty.textContent=searchQuery?'Nenhuma sessão encontrada. Experimente outro artista, música ou crédito.':'Salve um programa em “Ver depois” para montar sua lista.';}};
 root.querySelectorAll('[data-program-filter]').forEach(b=>b.addEventListener('click',()=>{currentFilter=b.dataset.programFilter;root.querySelectorAll('[data-program-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));filter();},opt));
 root.querySelectorAll('[data-save-show]').forEach(b=>b.addEventListener('click',()=>{const ids=saved(),id=b.dataset.saveShow,index=ids.indexOf(id);if(index<0)ids.push(id);else ids.splice(index,1);try{localStorage.setItem('meeting.points.watchlist',JSON.stringify(ids));root.querySelectorAll(`[data-save-show="${id}"]`).forEach(x=>{x.setAttribute('aria-pressed',String(index<0));x.textContent=index<0?'✓ Na sua lista':'+ Ver depois';});filter();}catch{b.textContent='Não foi possível salvar';}},opt));
 const s=shows.find(s=>s.id===root.querySelector('[data-show-id]')?.dataset.showId),theater=root.querySelector('.tv-theater');

 let controller;
 const updateTime=seconds=>{root.querySelector('.tv-external').href=watchURL(s.video,seconds);let active=null;root.querySelectorAll('[data-chapter]').forEach(a=>{a.removeAttribute('aria-current');if(Number(a.dataset.chapter)<=seconds)active=a;});active?.setAttribute('aria-current','true');};
 const play=(start=0)=>{if(!canEmbed(s))return;document.querySelector('.audio-dock audio')?.pause();controller??=createYouTubePlayer({container:root.querySelector('.tv-player'),video:s.video,title:s.artist+' — '+s.title,status:root.querySelector('.tv-player-status'),onTime:updateTime,onStart:()=>document.querySelector('.audio-dock audio')?.pause()});controller.play(start);theater.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});};
 root.querySelectorAll('[data-play-program]').forEach(b=>b.addEventListener('click',()=>play(),opt));
 root.querySelectorAll('[data-chapter]').forEach(a=>a.addEventListener('click',e=>{if(!canEmbed(s)||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;if(controller?.unavailable){updateTime(Number(a.dataset.chapter));return;}e.preventDefault();play(Number(a.dataset.chapter));},opt));
 const cinema=root.querySelector('[data-cinema]');const lights=on=>{document.body.classList.toggle('tv-cinema',on);cinema?.setAttribute('aria-pressed',String(on));if(cinema)cinema.textContent=on?'Acender as luzes ◑':'Apagar as luzes ◐';};
 cinema?.addEventListener('click',()=>{lights(!document.body.classList.contains('tv-cinema'));theater.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});},opt);
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('tv-cinema')){lights(false);cinema?.focus();}},opt);
 dispose=()=>{events.abort();controller?.destroy();};
}

export function searchShows(q,kind='all'){
 return shows.filter(s=>{const people=[s.artist,...s.credits.map(c=>c[1])],words=kind==='person'?people:kind==='year'?[String(s.year)]:kind==='genre'?[s.kind,...(s.tags||[])]:[s.title,s.artist,s.kind,String(s.year),s.place,...people,...s.sections.flatMap(x=>[x.heading,x.text]),...(s.repertoire||[]),...s.chapters.map(c=>c.title)];return words.some(v=>fold(v).includes(fold(q)));});
}
export function tvSearchResults(q,kind='all'){const list=searchShows(q,kind);return `<section class="tv-search-results"><div class="section-head"><h2>Na TV</h2><span class="small">${list.length} ${list.length===1?'sessão':'sessões'}</span></div>${list.length?`<div class="tv-program-grid">${list.map(card).join('')}</div>`:'<p class="small">Nenhuma sessão com esse termo no arquivo.</p>'}</section>`;}
